-- Backend Engineering ("The Fracture") Act 25 -- "Observability & Production" content.
-- Opens Arc VII (Operate). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be25', 'world-be-25', 'observability-and-production', '25A - Observability & Production', 'Leadership just asked a question Forge could not yet answer: how would anyone know something started going wrong, not after a citizen complains, but before. This Act builds the eyes -- logs, metrics, traces, dashboards, alerts and error budgets -- and opens Arc VII by finally pointing all of it at the pattern it has been tracking since Act 2.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be25-1', 'campaign-be25', 'the-raw-signals', 'The Raw Signals', 'Structured logs, log levels, correlation IDs, metrics, and the RED and USE methods -- the individual signals a running system can actually be made to produce.', 1),
  ('operation-be25-2', 'campaign-be25', 'watching-the-system', 'Watching the System', 'Distributed tracing, OpenTelemetry, dashboards, alerts and error budgets -- turning raw signals into a system that watches itself, continuously.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be25-01', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'structured-logging', 'Structured Logging', 'A postmortem should not take forty minutes of grep to answer a question the data already contained. Structured logging is the difference between a log a human can barely skim and a log a system can actually query.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"structured-logging-sim"}'::jsonb, '{"xp":291,"credits":56}'::jsonb, false, 1),
  ('mission-be25-02', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'log-levels', 'Log Levels', 'Five words -- debug, info, warn, error, fatal -- and an entire contract about who needs to be woken up and who can wait until morning. Get the mapping wrong and the pager either never rings or never stops.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be25-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"log-levels-sim"}'::jsonb, '{"xp":293,"credits":56}'::jsonb, false, 2),
  ('mission-be25-03', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'correlation-ids', 'Correlation IDs', 'One request now crosses however many services Act 23 split it into, and every one of them logs on its own timeline. A correlation ID is the one thread that pulls all of it back into a single story.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be25-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"correlation-ids-sim"}'::jsonb, '{"xp":295,"credits":57}'::jsonb, false, 3),
  ('mission-be25-04', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'metrics', 'Metrics', 'Logs describe one event at a time. Metrics describe the shape of everything, over time -- and the shape of a number matters more than any single event inside it.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be25-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"metrics-sim"}'::jsonb, '{"xp":297,"credits":57}'::jsonb, false, 4),
  ('mission-be25-05', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'red-method', 'The RED Method', 'Rate, Errors, Duration -- three questions that cover most of what actually goes wrong for anything serving requests, and the first method Forge stops reinventing per service.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be25-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"red-method-sim"}'::jsonb, '{"xp":299,"credits":57}'::jsonb, false, 5),
  ('mission-be25-06', 'world-be-25', 'campaign-be25', 'operation-be25-1', 'use-method', 'The USE Method', 'RED watches requests. USE watches the resources underneath them -- utilization, saturation, errors -- and catches failures that never show up as a request at all until it is too late.', 'advanced', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be25-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"use-method-sim"}'::jsonb, '{"xp":301,"credits":58}'::jsonb, false, 6),
  ('mission-be25-07', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'distributed-tracing', 'Distributed Tracing', 'A metric can tell you a request got slow. It cannot tell you which of the four services it passed through actually did that to it. A trace can.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be25-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"distributed-tracing-sim"}'::jsonb, '{"xp":303,"credits":58}'::jsonb, false, 7),
  ('mission-be25-08', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'opentelemetry-concepts', 'OpenTelemetry Concepts', 'Every service inventing its own tracing format was never going to scale past twenty Acts of services. OpenTelemetry is the vocabulary Forge finally agreed to share.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be25-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"opentelemetry-concepts-sim"}'::jsonb, '{"xp":305,"credits":58}'::jsonb, false, 8),
  ('mission-be25-09', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'dashboards', 'Dashboards', 'The data exists now. A dashboard is the difference between data that exists and data anyone actually looks at during an incident -- and most dashboards are built to look good in a demo, not to answer a question at 3am.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be25-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"dashboards-sim"}'::jsonb, '{"xp":307,"credits":59}'::jsonb, false, 9),
  ('mission-be25-10', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'alerts', 'Alerts', 'A dashboard nobody is staring at is still blind. An alert turns "someone could check this" into "someone gets paged" -- and a badly scoped one can sit silent through months of a real, ongoing failure.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be25-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"alerts-sim"}'::jsonb, '{"xp":309,"credits":59}'::jsonb, false, 10),
  ('mission-be25-11', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'sli-slo-and-error-budgets', 'SLI/SLO/Error Budgets', 'What you measure, what you promise, and how much failure that promise actually allows before it is broken. Three ideas that turn "reliable" from a feeling into a number Forge can be held to.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be25-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"slo-error-budget-sim"}'::jsonb, '{"xp":310,"credits":60}'::jsonb, false, 11),
  ('mission-be25-12', 'world-be-25', 'campaign-be25', 'operation-be25-2', 'the-five-percent', 'The Five Percent', 'The dashboards are live. The alerts are wired. Build the segmented SLO view the old aggregate one could never have shown -- and find out exactly how long something has been hiding inside a number that looked fine.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be25-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"five-percent-boss-sim"}'::jsonb, '{"xp":660,"credits":155,"badgeIds":["five-percent"],"skillXp":{"observability":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be25-01', 1, 'mira', 'Leadership asked a question this morning nobody in Forge could actually answer: how would we know something started going wrong -- not after a citizen complains, but before.'),
  ('mission-be25-01', 2, 'forge', 'That answer starts with the logs we already write. Most of them were never built to be asked questions -- they were built to be read by a human, scrolling, hoping to get lucky.'),
  ('mission-be25-01', 3, 'forge', 'A log line that is just a sentence is fine until you need to filter fifty million of them by user id at 3am. A log line that is actually a data structure, you can query.'),
  ('mission-be25-01', 4, 'mira', 'Start simple. Show me the difference between a log we can barely read and a log we can actually ask something.'),

  ('mission-be25-02', 1, 'forge', 'Five words -- debug, info, warn, error, fatal -- and an entire contract underneath them about who gets woken up and who can wait until morning.'),
  ('mission-be25-02', 2, 'forge', 'Log everything at ERROR and the pager never stops, so eventually someone silences it. Log a real failure at INFO and it never rings at all. Both mistakes end the same way.'),

  ('mission-be25-03', 1, 'mira', 'A single checkout request now crosses however many services Act 23 split it into. Every one of them logs on its own clock, in its own file.'),
  ('mission-be25-03', 2, 'forge', 'A correlation id is the one thread that survives every hop. Generate it at the edge, forward it on every call out, and the same string ties every log line back to the same request.'),

  ('mission-be25-04', 1, 'forge', 'Logs describe individual events. Metrics describe the shape of everything, over time -- counters that only climb, gauges that move freely, histograms that remember the distribution, not just one average.'),
  ('mission-be25-04', 2, 'mira', 'The shape of a number matters more than any single event buried inside it. That is the whole reason we are building this layer.'),

  ('mission-be25-05', 1, 'forge', 'For anything serving requests, three questions cover most of what actually goes wrong: how many, how many failing, how long. Rate, Errors, Duration. RED.'),
  ('mission-be25-05', 2, 'mira', 'Every service Forge runs should answer those three the same way, on the same kind of dashboard. Stop reinventing it per team.'),

  ('mission-be25-06', 1, 'forge', 'RED watches requests. USE watches the resources underneath them -- utilization, saturation, errors -- for the failures that never show up as a slow request until the resource is already out of room.'),
  ('mission-be25-06', 2, 'mira', 'A host can look perfectly healthy on utilization alone and still be the exact reason everything is backing up. That gap is what USE closes.'),

  ('mission-be25-07', 1, 'mira', 'A metric can tell you a request got slow. It cannot tell you which of the four services it passed through actually did that to it.'),
  ('mission-be25-07', 2, 'forge', 'A trace can. Every hop becomes a span, every span has a parent, and the whole thing reassembles into the actual path one request took across a system nobody can hold in their head anymore.'),

  ('mission-be25-08', 1, 'forge', 'If every service invents its own tracing format, nothing downstream can read any of it. OpenTelemetry is the vocabulary Forge finally agreed to share: traces, spans, context propagation, exporters, a collector in the middle.'),
  ('mission-be25-08', 2, 'forge', 'Learn the words once and it stops mattering which language wrote which service. That was never true before this.'),

  ('mission-be25-09', 1, 'mira', 'The data exists now. That is not the same as anyone actually looking at it during an incident.'),
  ('mission-be25-09', 2, 'forge', 'A dashboard built to look good in a demo and a dashboard built to answer a question at 3am are not the same artifact, even when they are drawing from the same metrics.'),

  ('mission-be25-10', 1, 'forge', 'A dashboard nobody is staring at is still blind. An alert is what turns "someone could check this" into "someone gets paged."'),
  ('mission-be25-10', 2, 'mira', 'A badly scoped alert is worse than no alert at all -- it gives everyone the false confidence that something would have told us. Get the scope wrong and it can sit silent through months of a real, ongoing failure.'),

  ('mission-be25-11', 1, 'mira', 'An SLI is what you actually measure. An SLO is the target you commit to. An error budget is how much failure that target already allows before it is broken.'),
  ('mission-be25-11', 2, 'forge', 'The budget is the part people forget. Ninety-nine point nine percent is not "basically never fails" -- it is a specific, spendable amount of failure, and you can burn through a whole month of it in a week if nobody is watching the rate.'),

  ('mission-be25-12', 1, 'mira', 'First week the new dashboards were live, and one of them did not say what any of us expected.'),
  ('mission-be25-12', 2, 'forge', 'I built the segmented view mostly out of stubbornness. One aggregate number was never going to tell us anything a citizen complaint would not already tell us faster.'),
  ('mission-be25-12', 3, 'forge', 'Turns out stubbornness was the right instinct. Walk the numbers with me before I tell you what they add up to.'),
  ('mission-be25-12', 4, 'mira', 'The aggregate said we were fine. The segment says we were not, and have not been for months.'),
  ('mission-be25-12', 5, 'forge', 'And the alert never told us, because it was never built to see a slice this small. Five percent, diluted across everything, does not move an all-traffic average anywhere near a threshold.'),
  ('mission-be25-12', 6, 'forge', 'So I did the thing I have wanted to do since Act 13. I cross-referenced that exact five percent against every "//" occurrence logged anywhere, all campaign, across every system we run.'),
  ('mission-be25-12', 7, 'forge', 'It lines up. Not roughly -- almost exactly. Five percent of all traffic, pathway-wide, silently burning its own error budget for months. That five percent is the "//"-tagged traffic.'),
  ('mission-be25-12', 8, 'mira', 'It was never rare. It was just never watched.'),
  ('mission-be25-12', 9, 'forge', 'I can tell you the shape of it now: continuous, quantified, five percent of everything, this whole time. I still cannot tell you what it is, who is behind it, or whether "deliberate" is even the right word for it.'),
  ('mission-be25-12', 10, 'mira', 'Do not let the size of that number answer questions we do not have evidence for. Quantified is not identified. But it changes what kind of problem this is -- an anomaly we noticed a few times a year just became a continuous five percent of everything we run.'),
  ('mission-be25-12', 11, 'forge', 'For the first time we are not finding this by accident. It is sitting in a dashboard, updating in real time, whether anyone looks at it or not.'),
  ('mission-be25-12', 12, 'mira', 'Then we look at it, on purpose, from now on. Arc VII begins here -- Forge can finally watch itself instead of finding out sideways. What comes next has to survive that scale for real: deployment, the cloud it actually runs on, the containers it ships in. That is where we start.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be25-01-o1', 'mission-be25-01', 1, 'Find the fix, not the symptom', 'Find the evidence that shows why structured logs actually solve the problem, not just describe it again.'),
  ('mission-be25-02-o1', 'mission-be25-02', 1, 'Match the level to its contract', 'Match each log level to what it actually promises about urgency.'),
  ('mission-be25-03-o1', 'mission-be25-03', 1, 'Find the real blocker', 'Find the evidence that explains why these logs cannot be stitched together, not just that the system is busy.'),
  ('mission-be25-03-o2', 'mission-be25-03', 2, 'Find the missing header', 'Debug the call that never forwards the correlation id downstream.'),
  ('mission-be25-04-o1', 'mission-be25-04', 1, 'Match the metric type', 'Match each metric type to what it is actually built to measure.'),
  ('mission-be25-05-o1', 'mission-be25-05', 1, 'Match the signal to the question', 'Match Rate, Errors and Duration to the question each one actually answers.'),
  ('mission-be25-05-o2', 'mission-be25-05', 2, 'Find what the average hides', 'Identify which RED signal is being hidden by a misleading average.'),
  ('mission-be25-06-o1', 'mission-be25-06', 1, 'Match USE to what it measures', 'Match Utilization, Saturation and Errors to what each one actually measures.'),
  ('mission-be25-06-o2', 'mission-be25-06', 2, 'Find the bottleneck utilization missed', 'Find the evidence that shows the real bottleneck a utilization-only check would have missed.'),
  ('mission-be25-07-o1', 'mission-be25-07', 1, 'Order the trace', 'Order the spans of a single request by when each one actually opens.'),
  ('mission-be25-08-o1', 'mission-be25-08', 1, 'Match the vocabulary', 'Match each OpenTelemetry term to what it actually refers to.'),
  ('mission-be25-09-o1', 'mission-be25-09', 1, 'Find what makes a dashboard actionable', 'Find the evidence that shows what actually makes a dashboard useful during an incident.'),
  ('mission-be25-10-o1', 'mission-be25-10', 1, 'Find the alert blind spot', 'Debug the alert rule that has never once fired for a real, ongoing failure.'),
  ('mission-be25-11-o1', 'mission-be25-11', 1, 'Match the vocabulary', 'Match SLI, SLO, error budget and burn rate to what each one actually is.'),
  ('mission-be25-11-o2', 'mission-be25-11', 2, 'Read the burn rate', 'Decide what an early, fast error-budget burn actually implies about the rest of the window.'),
  ('mission-be25-12-o1', 'mission-be25-12', 1, 'Pick the SLI that would have caught this', 'Choose the SLI actually capable of catching a failure hiding inside a small slice of traffic.'),
  ('mission-be25-12-o2', 'mission-be25-12', 2, 'Confirm the burn', 'Find the evidence that proves an SLO violation has actually been happening, not just a healthy aggregate number.'),
  ('mission-be25-12-o3', 'mission-be25-12', 3, 'Explain the blind spot', 'Find the evidence that explains the actual mechanism by which this stayed invisible to every alert.'),
  ('mission-be25-12-o4', 'mission-be25-12', 4, 'Name what the dashboard found', 'Synthesize the segmented SLO view into the reveal it was always building toward.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be25-01-o1-c1', 'mission-be25-01-o1', 1, 'investigation', 'Which evidence shows the actual fix, not just another symptom of the same problem?', '{"evidence":[{"id":"ev1","label":"Postmortem note","detail":"Every retro this month ends with the same line: grep -i error server.log took forty minutes and still missed the request that mattered"},{"id":"ev2","label":"Sample log line (unstructured)","detail":"2026-08-10 03:14:02 ERROR user 4482 failed checkout retry 3 timeout"},{"id":"ev3","label":"Sample log line (structured)","detail":"{\"timestamp\":\"2026-08-10T03:14:02Z\",\"level\":\"error\",\"userId\":4482,\"event\":\"checkout_failed\",\"attempt\":3,\"reason\":\"timeout\"}"}],"question":"Which evidence shows the actual fix, not just another symptom of the same problem?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be25-02-o1-c1', 'mission-be25-02-o1', 1, 'drag_and_drop', 'Match each log level to what it actually promises about urgency.', '{"items":[{"id":"l1","text":"DEBUG"},{"id":"l2","text":"INFO"},{"id":"l3","text":"WARN"},{"id":"l4","text":"ERROR"},{"id":"l5","text":"FATAL"}],"targets":[{"id":"t1","label":"Verbose detail useful only while actively debugging one specific issue, safe to disable in production"},{"id":"t2","label":"Confirms normal, expected behavior happened -- routine record-keeping"},{"id":"t3","label":"Something unexpected happened, but the system recovered and kept serving correctly"},{"id":"t4","label":"An operation failed and needs attention, but the service overall is still up"},{"id":"t5","label":"The service itself can no longer function and is about to, or already has, stopped"}]}'::jsonb, '{"correctMapping":{"l1":"t1","l2":"t2","l3":"t3","l4":"t4","l5":"t5"}}'::jsonb),

  ('mission-be25-03-o1-c1', 'mission-be25-03-o1', 1, 'investigation', 'Which evidence shows the actual blocker to correlating these events, not just a symptom of a busy system?', '{"evidence":[{"id":"ev1","label":"Service A log (checkout)","detail":"POST /checkout accepted, forwarded to payment service"},{"id":"ev2","label":"Service B log (payment)","detail":"payment declined -- no reference to which checkout request it belongs to"},{"id":"ev3","label":"Incident note","detail":"127 checkout requests logged in the same second across two services, with no shared identifier linking any checkout log line to its matching payment log line"}],"question":"Which evidence shows the actual blocker to correlating these events, not just a symptom of a busy system?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be25-03-o2-c1', 'mission-be25-03-o2', 1, 'code_debugging', 'This call receives a correlation id but never forwards it to the payment service. Which line is responsible?', '{"language":"javascript","code":"async function chargePayment(checkoutRequest, correlationId) {\n  const response = await fetch(\"https://payments.internal/charge\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(checkoutRequest)\n  });\n  return response.json();\n}","question":"This call receives a correlation id but never forwards it to the payment service. Which line is responsible?"}'::jsonb, '{"requiredLineIds":["    headers: { \"Content-Type\": \"application/json\" },"]}'::jsonb),

  ('mission-be25-04-o1-c1', 'mission-be25-04-o1', 1, 'drag_and_drop', 'Match each metric type to what it is actually built to measure.', '{"items":[{"id":"m1","text":"Counter"},{"id":"m2","text":"Gauge"},{"id":"m3","text":"Histogram"},{"id":"m4","text":"Summary"}],"targets":[{"id":"t1","label":"Only ever goes up, or resets to zero on restart -- total requests served, total errors"},{"id":"t2","label":"Moves up and down freely -- current memory usage, current queue depth"},{"id":"t3","label":"Buckets observations into ranges so percentiles can be computed later, and results aggregated across instances"},{"id":"t4","label":"Calculates percentiles client-side at collection time, at the cost of not being aggregatable across instances"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),

  ('mission-be25-05-o1-c1', 'mission-be25-05-o1', 1, 'drag_and_drop', 'Match Rate, Errors and Duration to the question each one actually answers.', '{"items":[{"id":"r1","text":"Rate"},{"id":"r2","text":"Errors"},{"id":"r3","text":"Duration"}],"targets":[{"id":"t1","label":"How many requests is this service handling per second right now?"},{"id":"t2","label":"What fraction of those requests are failing?"},{"id":"t3","label":"How long is each request actually taking, especially the slow tail?"}]}'::jsonb, '{"correctMapping":{"r1":"t1","r2":"t2","r3":"t3"}}'::jsonb),
  ('mission-be25-05-o2-c1', 'mission-be25-05-o2', 1, 'multiple_choice', 'A service average response time looks fine at 80ms, but citizens are filing complaints about slow checkouts. Which RED signal is most likely being hidden by that average?', '{"question":"A service average response time looks fine at 80ms, but citizens are filing complaints about slow checkouts. Which RED signal is most likely being hidden by that average?","options":[{"id":"a","text":"Rate -- the service is just handling more requests than usual"},{"id":"b","text":"Errors -- the requests are failing outright, not just running slow"},{"id":"c","text":"Duration, specifically the slow tail (p99) -- a few very slow requests get averaged away by many fast ones"},{"id":"d","text":"None of them, the average already tells the whole story"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be25-06-o1-c1', 'mission-be25-06-o1', 1, 'drag_and_drop', 'Match Utilization, Saturation and Errors to what each one actually measures.', '{"items":[{"id":"u1","text":"Utilization"},{"id":"u2","text":"Saturation"},{"id":"u3","text":"Errors"}],"targets":[{"id":"t1","label":"Percent of time the resource was busy doing work"},{"id":"t2","label":"Amount of extra work queued because the resource could not keep up right now"},{"id":"t3","label":"Count of error events reported by the resource itself -- dropped packets, failed allocations"}]}'::jsonb, '{"correctMapping":{"u1":"t1","u2":"t2","u3":"t3"}}'::jsonb),
  ('mission-be25-06-o2-c1', 'mission-be25-06-o2', 1, 'investigation', 'Which evidence shows the actual bottleneck the team missed by only checking utilization?', '{"evidence":[{"id":"ev1","label":"CPU utilization graph","detail":"Steady at 62 percent for the entire incident window"},{"id":"ev2","label":"Request queue depth graph","detail":"Climbed from 2 to 340 pending requests over the same window"},{"id":"ev3","label":"Team assumption","detail":"CPU looked fine, so the host itself was ruled out early in the investigation"}],"question":"Which evidence shows the actual bottleneck the team missed by only checking utilization?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be25-07-o1-c1', 'mission-be25-07-o1', 1, 'interactive_diagram', 'Order these spans by when each one actually opens, root first.', '{"diagramId":"trace-span-order","hotspots":[{"id":"gateway_span","label":"Gateway span (root)","explanation":"The trace starts here -- the first span, covering the entire request end to end."},{"id":"checkout_span","label":"Checkout service span","explanation":"A child of the root, opened the moment the gateway calls into checkout."},{"id":"payment_span","label":"Payment service span","explanation":"A child of the checkout span, opened when checkout calls out to payment."},{"id":"inventory_span","label":"Inventory service span","explanation":"Also a child of checkout, opened after payment succeeds, once checkout calls out to inventory."}],"task":"Order these spans by when each one actually opens, root first."}'::jsonb, '{"correctOrderIds":["gateway_span","checkout_span","payment_span","inventory_span"]}'::jsonb),

  ('mission-be25-08-o1-c1', 'mission-be25-08-o1', 1, 'drag_and_drop', 'Match each OpenTelemetry term to what it actually refers to.', '{"items":[{"id":"o1","text":"Trace"},{"id":"o2","text":"Span"},{"id":"o3","text":"Context Propagation"},{"id":"o4","text":"Exporter"},{"id":"o5","text":"Collector"}],"targets":[{"id":"t1","label":"The entire end-to-end record of one request across every service it touched"},{"id":"t2","label":"One timed unit of work within a trace, with its own start, end and attributes"},{"id":"t3","label":"Carrying the trace and span identifiers along with the request itself, hop to hop"},{"id":"t4","label":"The piece that sends collected telemetry out to a backend for storage and querying"},{"id":"t5","label":"A standalone process that receives, processes and forwards telemetry, decoupling services from any one backend"}]}'::jsonb, '{"correctMapping":{"o1":"t1","o2":"t2","o3":"t3","o4":"t4","o5":"t5"}}'::jsonb),

  ('mission-be25-09-o1-c1', 'mission-be25-09-o1', 1, 'investigation', 'Which evidence shows what actually makes a dashboard useful during an incident, not just satisfying to look at?', '{"evidence":[{"id":"ev1","label":"Dashboard A","detail":"Total requests served today: 4.2 million, big green number, trending up"},{"id":"ev2","label":"Dashboard B","detail":"p99 latency, error rate and saturation for each critical service, broken out per endpoint, with the last incident window highlighted"},{"id":"ev3","label":"Team note","detail":"Dashboard A gets projected in the office. Nobody has opened Dashboard B unprompted in three weeks."}],"question":"Which evidence shows what actually makes a dashboard useful during an incident, not just satisfying to look at?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be25-10-o1-c1', 'mission-be25-10-o1', 1, 'code_debugging', 'This alert has never fired even though one specific request class has been failing constantly. Which line explains why?', '{"language":"yaml","code":"alert: high_error_rate\nmetric: error_rate_percent\ncondition: avg(error_rate_percent) > 5\nwindow: 5m\nscope: all_traffic","question":"This alert has never fired even though one specific request class has been failing constantly. Which line explains why?"}'::jsonb, '{"requiredLineIds":["scope: all_traffic"]}'::jsonb),

  ('mission-be25-11-o1-c1', 'mission-be25-11-o1', 1, 'drag_and_drop', 'Match SLI, SLO, error budget and burn rate to what each one actually is.', '{"items":[{"id":"s1","text":"SLI"},{"id":"s2","text":"SLO"},{"id":"s3","text":"Error Budget"},{"id":"s4","text":"Burn Rate"}],"targets":[{"id":"t1","label":"The specific metric you actually measure -- e.g. percent of requests that succeed"},{"id":"t2","label":"The target you commit to for that metric -- e.g. 99.9 percent success over 30 days"},{"id":"t3","label":"The amount of allowed failure implied by the target -- 0.1 percent of requests, before the SLO is broken"},{"id":"t4","label":"How fast the allowed failure is being consumed relative to the time window -- normal pace, or fast enough to run out early"}]}'::jsonb, '{"correctMapping":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb),
  ('mission-be25-11-o2-c1', 'mission-be25-11-o2', 1, 'multiple_choice', 'A service has a 99.9 percent SLO (a 0.1 percent error budget) over 30 days. It has already used 0.08 percent of that budget in the first 5 days. What does that actually mean?', '{"question":"A service has a 99.9 percent SLO (a 0.1 percent error budget) over 30 days. It has already used 0.08 percent of that budget in the first 5 days. What does that actually mean?","options":[{"id":"a","text":"Nothing -- error budgets are informational only"},{"id":"b","text":"Most of the monthly error budget is already gone, in one sixth of the window -- at this rate the SLO will be broken well before the 30 days are up"},{"id":"c","text":"The service is comfortably within budget, since 0.08 is less than 0.1"},{"id":"d","text":"Error budgets only matter once they hit exactly zero"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be25-12-o1-c1', 'mission-be25-12-o1', 1, 'multiple_choice', 'Forge has one aggregate success-rate SLI covering all pathway traffic, sitting comfortably inside its SLO. Which additional SLI would actually be capable of catching a failure hiding inside a small slice of that traffic?', '{"question":"Forge has one aggregate success-rate SLI covering all pathway traffic, sitting comfortably inside its SLO. Which additional SLI would actually be capable of catching a failure hiding inside a small slice of that traffic?","options":[{"id":"a","text":"The same aggregate success rate, just checked more frequently"},{"id":"b","text":"Success rate segmented by request class or tag, so a slice that is failing cannot be diluted into the healthy majority"},{"id":"c","text":"Total request count, since more traffic means more scrutiny"},{"id":"d","text":"p50 latency across all traffic"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be25-12-o2-c1', 'mission-be25-12-o2', 1, 'investigation', 'Which evidence actually proves an SLO violation has been happening this whole time, not just a healthy aggregate number?', '{"evidence":[{"id":"ev1","label":"Aggregate SLI (all traffic)","detail":"99.95 percent success over the last 90 days -- comfortably inside the 99.9 percent SLO"},{"id":"ev2","label":"Segmented SLI (by request tag)","detail":"One specific request class, 5 percent of total volume, sits at 95.1 percent success over the same 90 days -- an error budget it exhausted in the first two weeks and has stayed over ever since"},{"id":"ev3","label":"Traffic mix","detail":"That request class has held steady at roughly 5 percent of total pathway volume for as long as anyone has telemetry for it"}],"question":"Which evidence actually proves an SLO violation has been happening this whole time, not just a healthy aggregate number?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be25-12-o3-c1', 'mission-be25-12-o3', 1, 'investigation', 'Which evidence explains the actual mechanism by which this stayed invisible, not just the fact that it stayed invisible?', '{"evidence":[{"id":"ev1","label":"Alert config","detail":"condition: avg(error_rate_percent) > 5, scope: all_traffic -- unchanged since it was written"},{"id":"ev2","label":"Dilution math","detail":"A slice that is 5 percent of traffic, even if entirely failing, only moves the all-traffic average by about 0.25 percentage points -- nowhere near a 5 percent aggregate threshold"},{"id":"ev3","label":"Alert history","detail":"Zero fires on this rule in the last 90 days, across the entire pathway"}],"question":"Which evidence explains the actual mechanism by which this stayed invisible, not just the fact that it stayed invisible?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be25-12-o4-c1', 'mission-be25-12-o4', 1, 'boss_encounter', 'Having picked the right SLI, confirmed the burn, and explained why no alert ever fired, state what the segmented dashboard actually found.', '{"stages":[{"objectiveRef":"mission-be25-12-o1","label":"Pick the SLI"},{"objectiveRef":"mission-be25-12-o2","label":"Confirm the burn"},{"objectiveRef":"mission-be25-12-o3","label":"Explain the blind spot"}],"task":"Having picked the right SLI, confirmed the burn, and explained why no alert ever fired, state what the segmented dashboard actually found: five percent of all traffic pathway-wide has been silently failing its own error budget for months, and cross-referencing that exact five percent against everything Forge has logged all campaign lines it up with the \"//\"-tagged traffic. It was never rare. It was just never watched."}'::jsonb, '{"requiredObjectiveIds":["mission-be25-12-o1","mission-be25-12-o2","mission-be25-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be25-01-o1-c1', 'orientation', 'Two of these describe the same problem. One describes what actually fixes it.', 10, 1),
  ('mission-be25-01-o1-c1', 'concept', 'A human squinting at a sentence and a machine querying a field are not solving the problem the same way -- only one of the two log lines supports the second approach at all.', 20, 2),
  ('mission-be25-01-o1-c1', 'solution', 'ev3: the structured line can be filtered by userId, event, attempt or reason directly -- the unstructured line still requires text search over every word.', 30, 3),

  ('mission-be25-02-o1-c1', 'orientation', 'Order them by how much you would want to be woken up for each one.', 10, 1),
  ('mission-be25-02-o1-c1', 'concept', 'DEBUG and INFO never page anyone. WARN and ERROR describe a failure that already happened at different severities. FATAL means the process itself cannot continue.', 20, 2),
  ('mission-be25-02-o1-c1', 'solution', 'DEBUG -> verbose detail, safe to disable; INFO -> routine record-keeping; WARN -> recovered but unexpected; ERROR -> a failed operation, service still up; FATAL -> the service itself cannot continue.', 30, 3),

  ('mission-be25-03-o1-c1', 'orientation', 'Two of these are just individual log lines. One is a statement about what links them, or does not.', 10, 1),
  ('mission-be25-03-o1-c1', 'concept', 'Busy is not the same as unlinkable -- 127 requests in a second is only a real problem if nothing in either log distinguishes which checkout matches which payment.', 20, 2),
  ('mission-be25-03-o1-c1', 'solution', 'ev3: with no shared identifier between the two logs, high volume in the same second makes matching a checkout to its payment log genuinely impossible, not just tedious.', 30, 3),
  ('mission-be25-03-o2-c1', 'orientation', 'The function already receives a correlationId parameter -- check whether it is actually used anywhere.', 10, 1),
  ('mission-be25-03-o2-c1', 'concept', 'A correlation id has to be forwarded explicitly, usually as a header, on every outbound call -- nothing propagates it automatically.', 20, 2),
  ('mission-be25-03-o2-c1', 'solution', 'The headers object only sets Content-Type -- correlationId is received but never added as an outbound header, so payment has no way to link its logs back to this request.', 30, 3),

  ('mission-be25-04-o1-c1', 'orientation', 'Two of these move in one direction only. Two of these can move freely, but differ in how they summarize a spread of values.', 10, 1),
  ('mission-be25-04-o1-c1', 'concept', 'A histogram keeps enough shape to compute percentiles after aggregating across every instance; a summary computes them per instance and cannot be combined the same way.', 20, 2),
  ('mission-be25-04-o1-c1', 'solution', 'Counter -> only increases, gauge -> moves freely, histogram -> bucketed for aggregatable percentiles, summary -> percentiles computed locally, not aggregatable.', 30, 3),

  ('mission-be25-05-o1-c1', 'orientation', 'One word means volume, one means failure, one means time.', 10, 1),
  ('mission-be25-05-o1-c1', 'solution', 'Rate -> requests per second, Errors -> fraction failing, Duration -> how long each request takes, especially the slow tail.', 20, 2),
  ('mission-be25-05-o2-c1', 'orientation', 'An average is a single number standing in for a whole distribution -- ask what that distribution could look like underneath it.', 10, 1),
  ('mission-be25-05-o2-c1', 'solution', 'c: a handful of very slow requests can sit in the tail while many fast ones pull the average back down to something that looks fine.', 20, 2),

  ('mission-be25-06-o1-c1', 'orientation', 'One is "how busy," one is "how backed up," one is "how many things reported broken."', 10, 1),
  ('mission-be25-06-o1-c1', 'solution', 'Utilization -> percent time busy, Saturation -> queued extra work, Errors -> error events reported by the resource itself.', 20, 2),
  ('mission-be25-06-o2-c1', 'orientation', 'Utilization alone answers "was it busy." It does not answer "was it keeping up."', 10, 1),
  ('mission-be25-06-o2-c1', 'concept', 'A resource can be under 100 percent utilization and still be the bottleneck if work is queuing up faster than it can be drained.', 20, 2),
  ('mission-be25-06-o2-c1', 'solution', 'ev2: the queue depth climbing from 2 to 340 is the actual saturation signal utilization alone completely missed.', 30, 3),

  ('mission-be25-07-o1-c1', 'orientation', 'A span cannot open before whatever called it has already started.', 10, 1),
  ('mission-be25-07-o1-c1', 'concept', 'Follow the actual call chain: gateway calls checkout, checkout calls payment, then checkout calls inventory after payment succeeds.', 20, 2),
  ('mission-be25-07-o1-c1', 'solution', 'Gateway span first (root), then checkout, then payment, then inventory.', 30, 3),

  ('mission-be25-08-o1-c1', 'orientation', 'Two of these are the "what happened" nouns. Two are "how it gets there" verbs.', 10, 1),
  ('mission-be25-08-o1-c1', 'concept', 'A trace is made of spans. Context propagation is how the trace and span ids travel with the request. An exporter and a collector both move data out, but only one of them is a standalone middle process.', 20, 2),
  ('mission-be25-08-o1-c1', 'solution', 'Trace -> the whole request record, Span -> one unit of work, Context Propagation -> carrying ids hop to hop, Exporter -> sends data to a backend, Collector -> a standalone middle process decoupling services from any one backend.', 30, 3),

  ('mission-be25-09-o1-c1', 'orientation', 'One dashboard answers a question you would actually have during an incident. One just looks reassuring.', 10, 1),
  ('mission-be25-09-o1-c1', 'concept', 'A big trending-up number says nothing about which specific endpoint is currently failing or how badly -- an actionable dashboard has to be broken out enough to point somewhere.', 20, 2),
  ('mission-be25-09-o1-c1', 'solution', 'ev2: per-service, per-endpoint p99 latency, error rate and saturation, with the incident window highlighted, is what actually helps during an incident -- a raw total does not.', 30, 3),

  ('mission-be25-10-o1-c1', 'orientation', 'Read the scope line -- ask what it means for a small, consistently-failing slice of traffic.', 10, 1),
  ('mission-be25-10-o1-c1', 'concept', 'An average computed over all traffic dilutes any failure confined to a small fraction of it, no matter how badly that fraction is failing.', 20, 2),
  ('mission-be25-10-o1-c1', 'solution', 'scope: all_traffic -- the condition averages error rate across everything, so a consistently-failing minority never pushes the all-traffic average anywhere near the 5 percent threshold.', 30, 3),

  ('mission-be25-11-o1-c1', 'orientation', 'One is what you measure, one is the promise, one is the allowance, one is the pace.', 10, 1),
  ('mission-be25-11-o1-c1', 'solution', 'SLI -> the metric measured, SLO -> the target, Error Budget -> the allowed failure implied by the target, Burn Rate -> how fast that allowance is being consumed.', 20, 2),
  ('mission-be25-11-o2-c1', 'orientation', 'Compare how much of the window has passed against how much of the budget is already spent.', 10, 1),
  ('mission-be25-11-o2-c1', 'solution', 'b: 0.08 out of a 0.1 budget spent in 5 of 30 days is a burn rate that, left unchanged, exhausts the budget well before the window ends -- the raw "still under 0.1" comparison hides that.', 20, 2),

  ('mission-be25-12-o1-c1', 'orientation', 'An aggregate that already looks healthy cannot be the tool that catches a failure hiding inside a small slice of it.', 10, 1),
  ('mission-be25-12-o1-c1', 'solution', 'b: only a success rate segmented by request class keeps a small failing slice from being diluted into the healthy majority.', 20, 2),
  ('mission-be25-12-o2-c1', 'orientation', 'The aggregate and the segmented view are telling two different stories -- only one of them is the real one.', 10, 1),
  ('mission-be25-12-o2-c1', 'solution', 'ev2: 95.1 percent success on 5 percent of traffic, exhausting its own error budget within two weeks and staying over ever since, is the actual SLO violation the aggregate was hiding.', 20, 2),
  ('mission-be25-12-o3-c1', 'orientation', 'The alert history proves it never fired. It does not explain why not -- look for the evidence that does the arithmetic.', 10, 1),
  ('mission-be25-12-o3-c1', 'solution', 'ev2: a fully-failing 5 percent slice only shifts an all-traffic average by about 0.25 points -- far short of the 5 percent threshold the alert was scoped against, so it could never have fired.', 20, 2),
  ('mission-be25-12-o4-c1', 'orientation', 'Look at what the three findings add up to together, not any one of them alone.', 15, 1),
  ('mission-be25-12-o4-c1', 'solution', 'Five percent of all traffic, pathway-wide, has been silently failing its own error budget for months -- and it lines up with the "//"-tagged traffic logged all campaign. It was never rare. It was just never watched.', 25, 2);
